// #36c6b2 — завершение молитвы без интернета (оба платформы) — עבר QA 19.11.2026 (подтвердил пользователь).
//   Факт: офлайн «סיים תפילה»; при диалоге «לא ידוע אם התפילה כבר נרשמה היום» — подтвердить «סיים תפילה» в диалоге → текст
//   «אין חיבור לאינטרנט. התפילה נשמרה במכשיר ותירשם כשהחיבור יחזור.»; после возврата сети «סה״כ תפילות» +1 и в «תפילות אחרונות» появляется запись.
// @data: ДОБАВЛЯЕТ запись в историю тестового аккаунта (счётчик «סה״כ תפילות» +1) — отменить нельзя. Запуск только с QA_RECORD_PRAYER=1
// и QA_OFFLINE_MANUAL=1 (режим полёта — человек, как в qa-2510 q-14). @manual-check. Кейс: .qa/tests/phone/qa-2026-11-19.md (Q19-04e).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, swipeUp } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import {
  goHome, waitHuman, openCatalogPrayer, nodes, counter, button, MANUAL_WAIT,
} from '../_lib/readiness-1910.ts';
import { coldStart, offlineBannerShown, recentFirstRow, OFF_BANNER } from '../_lib/app-2510.ts';
import { OFF_FINISH_UNKNOWN, OFF_FINISH_SAVED, allButtons, saveShot } from '../_lib/app-1911.ts';

const PRAYER = 'שחרית';
let baseTotal = -1;
let baseRow: { prayer: string; when: string } | null = null;

describe('19.11 — без интернета: завершение молитвы и синхронизация (#36c6b2)', function () {
  before(function () {
    if (process.env.QA_OFFLINE_MANUAL !== '1') skipWith(this, 'сеть выключает человек — запуск с QA_OFFLINE_MANUAL=1');
    if (process.env.QA_RECORD_PRAYER !== '1') skipWith(this, '@data: тест добавляет запись в историю аккаунта — запуск с QA_RECORD_PRAYER=1');
  });

  it('Q19-04e С интернетом запомнить «סה״כ תפילות» и первую строку «תפילות אחרונות»; режим полёта (человек) → холодный старт #36c6b2 @data @manual-check', async function () {
    this.timeout(MANUAL_WAIT + 600000);
    await goHome();
    baseTotal = await counter('סה״כ תפילות');
    baseRow = await recentFirstRow();
    console.log(`[Q-39] до: סה״כ תפילות = ${baseTotal}; первая запись: ${JSON.stringify(baseRow)}`);
    await openCatalogPrayer(PRAYER);                      // чтобы текст был в кэше
    await goHome();
    await waitHuman('ВКЛЮЧИТЕ режим полёта (Wi‑Fi и сотовая выкл.), приложение не закрывать. Тест ждёт баннер «אין חיבור לאינטרנט».', offlineBannerShown);
    await coldStart('офлайн старт');
    await expect(byTextContains(OFF_BANNER)).toBeExisting({ wait: 20000 });
  });

  it('Q19-04f Офлайн «סיים תפילה» (+ «סיים תפילה» в диалоге «לא ידוע אם התפילה כבר נרשמה היום») → «אין חיבור לאינטרנט. התפילה נשמרה במכשיר ותירשם כשהחיבור יחזור.» #36c6b2 @data @manual-check', async function () {
    this.timeout(300000);
    expect(baseTotal).toBeGreaterThanOrEqual(0);
    await openCatalogPrayer(PRAYER);
    const fin = await button('סיים תפילה');
    for (let i = 0; i < 12 && !(await fin.isDisplayed().catch(() => false)); i++) await swipeUp();
    await fin.click();

    // Диалог «לא ידוע אם התפילה כבר נרשמה היום» — подтвердить кнопкой «סיים תפילה» в диалоге (она последняя по порядку).
    await driver.waitUntil(async () => (await shown(byTextContains(OFF_FINISH_UNKNOWN))) || (await shown(byTextContains(OFF_FINISH_SAVED))),
      { timeout: 20000, interval: 700, timeoutMsg: 'после офлайн «סיים תפילה» нет ни диалога «לא ידוע…», ни «התפילה נשמרה במכשיר»' });
    if (await shown(byTextContains(OFF_FINISH_UNKNOWN))) {
      await saveShot('q39-offline-unknown-dialog.png');
      const btns = await allButtons('סיים תפילה');
      expect(btns.length).toBeGreaterThan(0);
      await btns[btns.length - 1].click();
    }
    await driver.waitUntil(async () => (await nodes()).some((n) => n.label.includes(OFF_FINISH_SAVED)),
      { timeout: 20000, interval: 1000, timeoutMsg: `нет текста «${OFF_FINISH_SAVED}»` });
    await saveShot('q39-offline-saved.png');
  });

  it('Q19-04g Сеть вернулась (человек): «סה״כ תפילות» +1 и в «תפילות אחרונות» новая запись #36c6b2 @data @manual-check', async function () {
    this.timeout(MANUAL_WAIT + 600000);
    await waitHuman('ВЫКЛЮЧИТЕ режим полёта. Тест ждёт, пока баннер «אין חיבור לאינטרנט» пропадёт (при необходимости «נסו שוב»).',
      async () => (await shown(byText('בית'))) && !(await offlineBannerShown()));
    await driver.waitUntil(async () => { await goHome(); return (await counter('סה״כ תפילות')) === baseTotal + 1; },
      { timeout: 120000, interval: 5000, timeoutMsg: `«סה״כ תפילות» не стал ${baseTotal + 1} за 2 минуты после возврата сети` });
    const row = await recentFirstRow();
    console.log(`[Q-39] после: первая запись ${JSON.stringify(row)}`);
    expect(row).not.toBeNull();
    expect(row!.prayer).toBe(PRAYER);
    if (baseRow) expect(row!.when).not.toBe(baseRow.when);
    await saveShot('q39-after-sync.png');
  });

  after(async function () {
    this.timeout(MANUAL_WAIT);
    if (process.env.QA_OFFLINE_MANUAL !== '1') return;
    if (await offlineBannerShown().catch(() => false)) {
      await waitHuman('тест закончился с выключенной сетью — ВЫКЛЮЧИТЕ режим полёта', async () => !(await offlineBannerShown()));
    }
  });
});
